export const speciesIcon = (slug, size = 24) =>
  PATHS[slug]
    ? `<svg viewBox="0 0 512 512" width="${size}" height="${size}" fill="currentColor" aria-hidden="true"><path d="${PATHS[slug]}"/></svg>`
    : icon.people(size);
export const SPECIES_ICON_SLUGS = Object.keys(PATHS);
